#!/usr/bin/env python3
"""Generate interface/register docs and a C header from data/<ip>.yaml.

Usage:
    python gen_docs.py <ip_dir> [--check]

Outputs (relative to <ip_dir>):
    doc/03_interfaces.md
    doc/04_registers.md
    sw/<ip>_regs.h

--check  only validate the data file and report whether generated files are stale.
"""
import argparse
import json
import re
import sys
from pathlib import Path

GEN_MARK = "<!-- AUTO-GENERATED by rtl-flow gen_docs.py from {src}. DO NOT EDIT. -->"

SWACCESS = {"ro", "rw", "wo", "rc", "rw1c", "rw1s", "rw0c", "r0w1c"}
HWACCESS = {"hro", "hrw", "hwo", "none"}
DIRS = {"input", "output", "inout"}


# --------------------------------------------------------------------------- load
def find_data_file(ip_dir: Path) -> Path:
    cands = [p for ext in ("yaml", "yml", "json", "hjson") for p in (ip_dir / "data").glob(f"*.{ext}")]
    if len(cands) != 1:
        raise SystemExit(f"ERROR: expected exactly one data file in {ip_dir / 'data'}, found {len(cands)}")
    return cands[0]


def load_data(path: Path) -> dict:
    text = path.read_text(encoding="utf-8")
    if path.suffix in (".yaml", ".yml"):
        import yaml
        return yaml.safe_load(text)
    if path.suffix == ".hjson":
        try:
            import hjson
        except ImportError:
            raise SystemExit("ERROR: .hjson data file requires `pip install hjson` (or use .yaml)")
        return json.loads(json.dumps(hjson.loads(text)))
    return json.loads(text)


def to_int(v):
    if isinstance(v, int):
        return v
    return int(str(v), 0)


def parse_bits(bits):
    s = str(bits).strip()
    if ":" in s:
        hi, lo = (int(x) for x in s.split(":"))
    else:
        hi = lo = int(s)
    return hi, lo


# --------------------------------------------------------------------------- validate
def validate(d: dict) -> list:
    errs = []
    for key in ("name", "version", "desc", "top", "rtl_files", "clocks", "resets", "ports"):
        if key not in d or d[key] in (None, ""):
            errs.append(f"missing top-level field '{key}'")
    if errs:
        return errs
    if not re.fullmatch(r"[a-z][a-z0-9_]*", str(d["name"])):
        errs.append(f"name '{d['name']}' must be lower_snake_case")

    port_names = set()
    for p in d.get("ports") or []:
        n = p.get("name")
        if n in port_names:
            errs.append(f"duplicate port '{n}'")
        port_names.add(n)
        if p.get("dir") not in DIRS:
            errs.append(f"port '{n}': dir must be one of {sorted(DIRS)}")
        if "width" not in p:
            errs.append(f"port '{n}': missing width")
        suffix_ok = {"input": ("_i", "_ni"), "output": ("_o", "_no"), "inout": ("_io",)}.get(p.get("dir"), ())
        if suffix_ok and not str(n).endswith(suffix_ok):
            errs.append(f"port '{n}': name should end with {'/'.join(suffix_ok)} (see glossary)")
    for c in d.get("clocks") or []:
        if c.get("name") not in port_names:
            errs.append(f"clock '{c.get('name')}' is not listed in ports")
    for r in d.get("resets") or []:
        if r.get("name") not in port_names:
            errs.append(f"reset '{r.get('name')}' is not listed in ports")

    dw = int((d.get("bus") or {}).get("data_width", 32))
    offsets = {}
    for r in d.get("registers") or []:
        rn = r.get("name", "?")
        if not re.fullmatch(r"[A-Z][A-Z0-9_]*", str(rn)):
            errs.append(f"register '{rn}': name must be UPPER_SNAKE_CASE")
        try:
            off = to_int(r.get("offset"))
        except (TypeError, ValueError):
            errs.append(f"register '{rn}': invalid offset {r.get('offset')!r}")
            continue
        if off % (dw // 8):
            errs.append(f"register '{rn}': offset {off:#x} not aligned to {dw // 8} bytes")
        if off in offsets:
            errs.append(f"register '{rn}': offset {off:#x} collides with '{offsets[off]}'")
        offsets[off] = rn
        used = 0
        for f in r.get("fields") or []:
            fn = f"{rn}.{f.get('name', '?')}"
            try:
                hi, lo = parse_bits(f.get("bits"))
            except (TypeError, ValueError):
                errs.append(f"{fn}: invalid bits {f.get('bits')!r}")
                continue
            if hi < lo or hi >= dw:
                errs.append(f"{fn}: bits [{hi}:{lo}] out of range for {dw}-bit register")
                continue
            mask = ((1 << (hi - lo + 1)) - 1) << lo
            if used & mask:
                errs.append(f"{fn}: bits [{hi}:{lo}] overlap another field")
            used |= mask
            if f.get("swaccess") not in SWACCESS:
                errs.append(f"{fn}: swaccess '{f.get('swaccess')}' not in {sorted(SWACCESS)}")
            if f.get("hwaccess", "hro") not in HWACCESS:
                errs.append(f"{fn}: hwaccess '{f.get('hwaccess')}' not in {sorted(HWACCESS)}")
            try:
                rv = to_int(f.get("resval", 0))
                if rv >> (hi - lo + 1):
                    errs.append(f"{fn}: resval {rv:#x} does not fit in {hi - lo + 1} bits")
            except (TypeError, ValueError):
                errs.append(f"{fn}: invalid resval {f.get('resval')!r}")
        if not r.get("fields"):
            errs.append(f"register '{rn}': no fields")
    return errs


# --------------------------------------------------------------------------- render helpers
def front_matter(doc: str, d: dict) -> str:
    return (f"---\ndoc: {doc}\nip: {d['name']}\nversion: {d['version']}\n"
            f"status: Generated\nsource: data/{d['_src']}\n---\n\n")


def table(headers, rows) -> str:
    def cell(x):
        return str("" if x is None else x).replace("|", "\\|").replace("\n", " ")
    out = ["| " + " | ".join(headers) + " |", "|" + "---|" * len(headers)]
    out += ["| " + " | ".join(cell(c) for c in row) + " |" for row in rows]
    return "\n".join(out) + "\n"


def width_str(w):
    if isinstance(w, int):
        return "1" if w == 1 else f"[{w - 1}:0]"
    return f"[{w}-1:0]"


def reg_resval(r) -> int:
    v = 0
    for f in r.get("fields") or []:
        _, lo = parse_bits(f["bits"])
        v |= to_int(f.get("resval", 0)) << lo
    return v


# --------------------------------------------------------------------------- generators
def gen_interfaces(d: dict) -> str:
    s = front_matter("03_interfaces", d)
    s += GEN_MARK.format(src=f"data/{d['_src']}") + "\n\n"
    s += f"# {d['name']} 接口\n\n{d['desc']}\n\n"
    s += f"- 顶层模块：`{d['top']}`\n- IP 版本：{d['version']}\n\n"

    s += "## 1. 参数 (Parameters)\n\n"
    params = [p for p in d.get("params") or [] if not p.get("local")]
    s += table(["名称", "类型", "默认值", "描述"],
               [[f"`{p['name']}`", p.get("type", "int"), p.get("default"), p.get("desc")] for p in params]) \
        if params else "无。\n"

    s += "\n## 2. 时钟 (Clocks)\n\n"
    s += table(["名称", "频率 (MHz)", "描述"],
               [[f"`{c['name']}`", c.get("freq_mhz"), c.get("desc")] for c in d["clocks"]])

    s += "\n## 3. 复位 (Resets)\n\n"
    s += table(["名称", "有效电平", "类型", "关联时钟", "描述"],
               [[f"`{r['name']}`", r.get("active"), r.get("type"), f"`{r.get('clock')}`", r.get("desc")]
                for r in d["resets"]])

    s += "\n## 4. 端口 (Ports)\n\n"
    s += table(["名称", "方向", "位宽", "时钟域", "描述"],
               [[f"`{p['name']}`", p["dir"], width_str(p["width"]), p.get("clock"), p.get("desc")]
                for p in d["ports"]])

    s += "\n## 5. 中断 (Interrupts)\n\n"
    irqs = d.get("interrupts") or []
    s += table(["名称", "类型", "描述"], [[f"`{i['name']}`", i.get("type"), i.get("desc")] for i in irqs]) \
        if irqs else "无。\n"

    s += "\n## 6. 总线 (Bus)\n\n"
    bus = d.get("bus")
    s += table(["协议", "数据位宽", "地址位宽"],
               [[bus.get("protocol"), bus.get("data_width", 32), bus.get("addr_width")]]) if bus else "无。\n"
    return s


def gen_registers(d: dict) -> str:
    regs = sorted(d.get("registers") or [], key=lambda r: to_int(r["offset"]))
    dw = int((d.get("bus") or {}).get("data_width", 32))
    s = front_matter("04_registers", d)
    s += GEN_MARK.format(src=f"data/{d['_src']}") + "\n\n"
    s += f"# {d['name']} 寄存器\n\n"
    s += f"数据位宽 {dw} bit，偏移为相对 IP 基地址的字节偏移。访问类型定义见术语表。\n\n"

    s += "## 1. 寄存器总览 (Summary)\n\n"
    if not regs:
        return s + "无寄存器。\n\n## 2. 寄存器详情 (Details)\n\n无。\n"
    s += table(["偏移", "名称", "复位值", "描述"],
               [[f"0x{to_int(r['offset']):03X}", f"[`{r['name']}`](#{r['name'].lower()})",
                 f"0x{reg_resval(r):0{dw // 4}X}", r.get("desc")] for r in regs])

    s += "\n## 2. 寄存器详情 (Details)\n"
    for r in regs:
        s += f"\n### {r['name']}\n\n"
        s += f"- 偏移：`0x{to_int(r['offset']):03X}`\n- 复位值：`0x{reg_resval(r):0{dw // 4}X}`\n"
        s += f"- 描述：{r.get('desc', '')}\n\n"
        fields = sorted(r["fields"], key=lambda f: parse_bits(f["bits"])[1])
        # WaveDrom bit-field diagram, LSB first, with gaps filled
        wd, pos = [], 0
        for f in fields:
            hi, lo = parse_bits(f["bits"])
            if lo > pos:
                wd.append({"bits": lo - pos})
            wd.append({"name": f["name"], "bits": hi - lo + 1, "attr": f["swaccess"]})
            pos = hi + 1
        if pos < dw:
            wd.append({"bits": dw - pos})
        s += "```wavedrom\n" + json.dumps({"reg": wd, "config": {"bits": dw, "lanes": max(1, dw // 16)}},
                                          ensure_ascii=False) + "\n```\n\n"
        rows = []
        for f in reversed(fields):
            hi, lo = parse_bits(f["bits"])
            desc = f.get("desc", "")
            if f.get("enum"):
                desc += "<br>" + "<br>".join(f"`{e['value']}` {e['name']}: {e.get('desc', '')}" for e in f["enum"])
            rows.append([f"[{hi}:{lo}]" if hi != lo else f"[{lo}]", f"`{f['name']}`", f["swaccess"],
                         f.get("hwaccess", "hro"), hex(to_int(f.get("resval", 0))), desc])
        s += table(["位", "字段", "SW", "HW", "复位值", "描述"], rows)
    return s


def gen_c_header(d: dict) -> str:
    p = d["name"].upper()
    g = f"{p}_REGS_H_"
    out = [f"// AUTO-GENERATED by rtl-flow gen_docs.py from data/{d['_src']}. DO NOT EDIT.",
           f"#ifndef {g}", f"#define {g}", ""]
    for r in sorted(d.get("registers") or [], key=lambda r: to_int(r["offset"])):
        rn = f"{p}_{r['name']}"
        out.append(f"// {r.get('desc', '')}")
        out.append(f"#define {rn}_REG_OFFSET 0x{to_int(r['offset']):x}u")
        out.append(f"#define {rn}_REG_RESVAL 0x{reg_resval(r):x}u")
        for f in sorted(r["fields"], key=lambda f: parse_bits(f["bits"])[1]):
            hi, lo = parse_bits(f["bits"])
            fn = f"{rn}_{f['name']}"
            if hi == lo:
                out.append(f"#define {fn}_BIT {lo}")
            else:
                out.append(f"#define {fn}_MASK 0x{(1 << (hi - lo + 1)) - 1:x}u")
                out.append(f"#define {fn}_OFFSET {lo}")
            for e in f.get("enum") or []:
                out.append(f"#define {fn}_VALUE_{e['name'].upper()} 0x{to_int(e['value']):x}u")
        out.append("")
    out += [f"#endif  // {g}", ""]
    return "\n".join(out)


def outputs(ip_dir: Path):
    """Return (data, errors, {path: expected_content})."""
    src = find_data_file(ip_dir)
    d = load_data(src)
    if not isinstance(d, dict):
        return None, [f"{src}: top level must be a mapping"], {}
    d["_src"] = src.name
    errs = validate(d)
    if errs:
        return d, errs, {}
    files = {
        ip_dir / "doc" / "03_interfaces.md": gen_interfaces(d),
        ip_dir / "doc" / "04_registers.md": gen_registers(d),
        ip_dir / "sw" / f"{d['name']}_regs.h": gen_c_header(d),
    }
    return d, [], files


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("ip_dir", type=Path)
    ap.add_argument("--check", action="store_true", help="validate and report stale files without writing")
    a = ap.parse_args()

    _, errs, files = outputs(a.ip_dir)
    if errs:
        for e in errs:
            print(f"ERROR: data: {e}")
        sys.exit(1)
    stale = 0
    for path, content in files.items():
        cur = path.read_text(encoding="utf-8") if path.exists() else None
        if cur is not None and cur.replace("\r\n", "\n") == content:
            print(f"up-to-date  {path}")
            continue
        if a.check:
            print(f"STALE       {path}")
            stale += 1
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8", newline="\n")
            print(f"generated   {path}")
    sys.exit(1 if stale else 0)


if __name__ == "__main__":
    main()
